<?php
namespace App\Http\Controllers;use App\Models\MeasurementPoint;use App\Services\MeasurementQualityService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;
class MeasurementController extends Controller{public function store(Request $r,MeasurementPoint $measurementPoint,MeasurementQualityService $quality):JsonResponse{abort_unless($r->user()->can('measurements.create'),403);abort_if($measurementPoint->survey->status==='completed',422,'Completed surveys are immutable.');$d=$r->validate(['ssid'=>'nullable|string|max:100','bssid'=>'nullable|string|max:64','rssi_dbm'=>'nullable|integer|between:-120,0','download_mbps'=>'nullable|numeric|min:0|max:100000','upload_mbps'=>'nullable|numeric|min:0|max:100000','latency_ms'=>'nullable|numeric|min:0|max:100000','jitter_ms'=>'nullable|numeric|min:0|max:100000','packet_loss_percent'=>'nullable|numeric|between:0,100','channel'=>'nullable|integer|between:1,233','frequency_band'=>'nullable|in:2.4GHz,5GHz,6GHz,unknown','noise_floor_dbm'=>'nullable|integer|between:-150,0','source_type'=>'required|in:measured,imported,simulated','collection_method'=>'required|string|max:40','captured_at'=>'nullable|date','raw_payload'=>'nullable|array']);$d['bssid_hash']=isset($d['bssid'])?hash('sha256',strtolower($d['bssid'])):null;unset($d['bssid']);$d['is_simulated']=$d['source_type']==='simulated';$d['quality_flags']=$quality->flags($d);$d['captured_at']=$d['captured_at']??now();$m=$measurementPoint->measurements()->create($d);$measurementPoint->update(['validation_status'=>$quality->validationStatus($d['quality_flags'])]);return response()->json($m,201);}}
